create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, locale text not null default 'uz', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.providers (id uuid primary key default gen_random_uuid(), name text not null, kind text not null, status text not null default 'draft', secret_ref text, created_at timestamptz not null default now());
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null);
create table if not exists public.channels (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, country text, language text, category_id uuid references public.categories(id), status text not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.channel_variants (id uuid primary key default gen_random_uuid(), channel_id uuid not null references public.channels(id) on delete cascade, provider_id uuid references public.providers(id), external_id text, quality text, timeshift text, stream_fingerprint text, unique(provider_id, external_id));
create table if not exists public.content_rights (id uuid primary key default gen_random_uuid(), provider_id uuid not null references public.providers(id), rights_type text not null, territories text[] not null default '{}', starts_at timestamptz, ends_at timestamptz, document_ref text, status text not null default 'unconfirmed', admin_notes text);
create table if not exists public.favorites (user_id uuid not null references auth.users(id) on delete cascade, channel_id uuid not null references public.channels(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id, channel_id));
create table if not exists public.watch_history (user_id uuid not null references auth.users(id) on delete cascade, channel_id uuid not null references public.channels(id) on delete cascade, watched_at timestamptz not null default now(), seconds_watched integer not null default 0, primary key(user_id, channel_id));
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.favorites enable row level security; alter table public.watch_history enable row level security;
create policy "profiles own row" on public.profiles for all using (auth.uid() = id) with check (auth.uid() = id);
create policy "favorites own rows" on public.favorites for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "history own rows" on public.watch_history for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
